package dev.mando;
import io.papermc.paper.dialog.Dialog;import io.papermc.paper.registry.data.dialog.*;import io.papermc.paper.registry.data.dialog.action.DialogAction;import io.papermc.paper.registry.data.dialog.body.DialogBody;import io.papermc.paper.registry.data.dialog.type.DialogType;import net.kyori.adventure.text.Component;import net.kyori.adventure.text.event.ClickCallback;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class ChangelogCommand implements CommandExecutor{
 private final MandoPlugin plugin;public ChangelogCommand(MandoPlugin p){plugin=p;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage(plugin.msg("only-players"));return true;}show(p);return true;}
 private void show(Player p){String version=plugin.getPluginMeta().getVersion(),date=plugin.getConfig().getString("changelog.date","");List<String> lines=plugin.getConfig().getStringList("changelog.lines");StringBuilder body=new StringBuilder(date+" · Mando "+version+"\n\nCAMBIOS DE ESTA BUILD\n");for(String line:lines)body.append("• ").append(line).append("\n");String last=plugin.players().lastReadVersion(p.getUniqueId());if(last!=null&&!last.isBlank())body.append("\nÚltima versión leída: ").append(last);ActionButton ok=ActionButton.builder(Component.text("Entendido")).tooltip(Component.text("Marcar esta versión como leída")).action(DialogAction.customClick((r,a)->{if(a instanceof Player pl){plugin.players().setLastReadVersion(pl.getUniqueId(),version);pl.sendMessage(Component.text("Mando » Novedades marcadas como leídas."));}},ClickCallback.Options.builder().uses(1).build())).build();p.showDialog(Dialog.create(b->b.empty().base(DialogBase.builder(Component.text("Novedades de Mando")).body(List.of(DialogBody.plainMessage(Component.text(body.toString())))).build()).type(DialogType.notice(ok))));}
}